/** 基础统计函数，全部为纯函数便于测试 */

export function mean(values: number[]): number {
  if (values.length === 0) return 0;
  return values.reduce((a, b) => a + b, 0) / values.length;
}

export function std(values: number[]): number {
  if (values.length < 2) return 0;
  const m = mean(values);
  const variance = values.reduce((acc, v) => acc + (v - m) * (v - m), 0) / (values.length - 1);
  return Math.sqrt(variance);
}

export function min(values: number[]): number {
  if (values.length === 0) return 0;
  return values.reduce((a, b) => Math.min(a, b), Infinity);
}

export function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

export function round1(v: number): number {
  return Math.round(v * 10) / 10;
}

/** 将数组分为 10 个桶，用于反应时间分布展示 */
export function histogram(values: number[], buckets = 10): { lo: number; hi: number; count: number }[] {
  if (values.length === 0) return [];
  const lo = Math.min(...values);
  const hi = Math.max(...values);
  const width = (hi - lo) / buckets || 1;
  const result = Array.from({ length: buckets }, (_, i) => ({
    lo: lo + i * width,
    hi: lo + (i + 1) * width,
    count: 0,
  }));
  for (const v of values) {
    const idx = Math.min(buckets - 1, Math.floor((v - lo) / width));
    result[idx].count++;
  }
  return result;
}

