import type { Difficulty } from "../types";

/**
 * 时间轴约定：
 * - 所有时间戳均为 performance.now() 时钟（毫秒）。
 * - beatTime 为节拍“计划发声”的时刻（调度时刻）。
 * - 用户实际听到声音的时刻 = beatTime + audioLatencyMs。
 * - 用户敲击的物理时刻 = 事件时间戳 - inputLatencyMs。
 * 因此偏差 = (敲击事件时间 - 输入补偿) - (节拍时刻 + 输出延迟)。
 * 偏差 > 0 表示拖拍（晚），< 0 表示抢拍（早）。
 */
export function computeOffsetMs(
  tapEventTimeMs: number,
  beatTimeMs: number,
  audioLatencyMs: number,
  inputLatencyMs: number
): number {
  return tapEventTimeMs - inputLatencyMs - (beatTimeMs + audioLatencyMs);
}

/** 反应时间 = 输入事件时间 - 输入补偿 - 目标出现时间 */
export function computeReactionMs(
  inputEventTimeMs: number,
  targetShownTimeMs: number,
  inputLatencyMs: number
): number {
  return inputEventTimeMs - inputLatencyMs - targetShownTimeMs;
}

export function hitWindowMs(difficulty: Difficulty): number {
  switch (difficulty) {
    case "easy":
      return 150;
    case "hard":
      return 60;
    default:
      return 100;
  }
}

export function isHit(offsetMs: number, windowMs: number): boolean {
  return Math.abs(offsetMs) <= windowMs;
}

export type RhythmBias = "early" | "late" | "neutral";

export function rhythmBias(meanOffsetMs: number): RhythmBias {
  if (meanOffsetMs <= -20) return "early";
  if (meanOffsetMs >= 20) return "late";
  return "neutral";
}

/** 由偏差标准差推导 0..1 的稳定性，std 越小越稳定 */
export function stabilityFromStd(stdMs: number, scaleMs = 120): number {
  const v = 1 - stdMs / scaleMs;
  return Math.min(1, Math.max(0, v));
}

/** 校准：由一组偏差样本估算延迟（均值），并过滤超过 ±400ms 的异常值 */
export function estimateLatencyFromOffsets(offsetsMs: number[]): {
  meanMs: number;
  stdMs: number;
  used: number[];
} {
  const filtered = offsetsMs.filter((o) => Math.abs(o) <= 400);
  const used = filtered.length >= 4 ? filtered : offsetsMs.slice();
  if (used.length === 0) return { meanMs: 0, stdMs: 0, used };
  const m = used.reduce((a, b) => a + b, 0) / used.length;
  const variance =
    used.length > 1
      ? used.reduce((acc, v) => acc + (v - m) * (v - m), 0) / (used.length - 1)
      : 0;
  return { meanMs: m, stdMs: Math.sqrt(variance), used };
}

