  /** 相对测试开始的出现时刻（毫秒） */
  appearAtMs: number;
  /** 存活时长（毫秒），超时未点记为漏点 */
  lifetimeMs: number;
  /** 0..1，相对舞台的位置 */
  x: number;
  y: number;
  /** 直径 px */
  size: number;
  color: string;
  /** true 表示干扰刺激，需要抑制反应（不点击） */
  inhibit: boolean;
}

const COLORS = ["#4f8cff", "#ff8a4f", "#3ecf8e", "#c86bfa", "#ffd54f", "#4fd6ff"];
export const INHIBIT_COLOR = "#e5484d";

function targetLifetimeMs(difficulty: Difficulty): number {
  switch (difficulty) {
    case "easy":
      return 1600;
    case "hard":
      return 850;
    default:
      return 1200;
  }
}

function targetGapMs(difficulty: Difficulty): [number, number] {
  switch (difficulty) {
    case "easy":
      return [900, 1600];
    case "hard":
      return [450, 900];
    default:
      return [650, 1200];
  }
}

export interface TargetPlanOptions {
  durationMs: number;
  difficulty: Difficulty;
  seed: number;
  /** 是否生成需要抑制反应的干扰刺激（持续注意测试） */
  withInhibitors?: boolean;
  /** 目标频率是否随时间逐渐加快（持续注意测试） */
  rampUp?: boolean;
  /** 目标密度系数（双任务时降低密度） */
  densityScale?: number;
}

/**
 * 生成一次测试的视觉目标计划。位置、大小、颜色、出现时间均由种子随机，
 * 同一种子 + 同一配置生成完全相同的计划，保证不同配置之间可公平对比。
 */
export function generateTargetPlan(opts: TargetPlanOptions): TargetEvent[] {
  const rng = createRng(opts.seed);
  const lifetime = targetLifetimeMs(opts.difficulty);
  const [gapLo, gapHi] = targetGapMs(opts.difficulty);
  const density = opts.densityScale ?? 1;
  const events: TargetEvent[] = [];
  let t = 800 + rng() * 600; // 首个目标前的随机等待
  let id = 0;
  while (t < opts.durationMs - lifetime - 200) {
    const progress = t / opts.durationMs;
    const size = 40 + rng() * 50;
    const margin = 0.08;
    const inhibit = opts.withInhibitors ? rng() < 0.18 : false;
    events.push({
      id: id++,
      appearAtMs: t,
      lifetimeMs: lifetime * (0.9 + rng() * 0.2),
      x: margin + rng() * (1 - 2 * margin),
      y: margin + rng() * (1 - 2 * margin),
      size,
      color: inhibit ? INHIBIT_COLOR : COLORS[Math.floor(rng() * COLORS.length)],
      inhibit,
    });
    let gap = gapLo + rng() * (gapHi - gapLo);
    if (opts.rampUp) gap *= 1 - 0.45 * progress; // 频率逐渐提高
    t += gap / density;
  }
  return events;
}

export interface BeatEvent {
  index: number;
  /** 相对测试开始的计划发声时刻（毫秒） */
  timeMs: number;
  /** 是否重拍 */
  accent: boolean;
  /** 视觉提示颜色 */
  color: string;
}

/**
 * 生成节奏跟随测试的节拍计划。
 * 间隔在基础间隔上做 ±12% 的随机变化（保持累计时间对齐），
 * 重拍位置与提示颜色也会变化，避免完全固定。
 */
export function generateBeatPlan(
  durationMs: number,
  bpm: number,
  subdivision: number,
  seed: number
): BeatEvent[] {
  const rng = createRng(seed ^ 0x9e3779b9);
  const base = 60000 / bpm / subdivision;
  const beats: BeatEvent[] = [];
  let t = 1000; // 1 秒预备时间
  let index = 0;
  while (t < durationMs - 300) {
    beats.push({
      index,
      timeMs: t,
      accent: rng() < 0.25,
      color: COLORS[Math.floor(rng() * COLORS.length)],
    });
    const jitter = 1 + (rng() * 2 - 1) * 0.12;
    t += base * jitter;
    index++;
  }
  return beats;
}

