import type {
  AttentionMetrics,
  DualMetrics,
  ModeMetrics,
  ReactionMetrics,
  RhythmMetrics,
} from "../types";
import { clamp } from "./stats";

function scoreRhythm(m: RhythmMetrics): number {
  const hitPart = m.hitRate * 50;
  const stabPart = m.stability * 30;
  const comboPart = clamp(m.maxCombo / 12, 0, 1) * 20;
  return Math.round(hitPart + stabPart + comboPart);
}

function scoreReaction(m: ReactionMetrics): number {
  const hitPart = m.hitRate * 40;
  // 200ms 优秀，800ms 及格线
  const speedPart = clamp(1 - (m.meanRtMs - 200) / 600, 0, 1) * 40;
  const totalAttempts = m.hits + m.falseClicks;
  const accuracy = totalAttempts > 0 ? m.hits / totalAttempts : 0;
  return Math.round(hitPart + speedPart + accuracy * 20);
}

function scoreDual(m: DualMetrics): number {
  const base = (scoreRhythm(m.rhythm) + scoreReaction(m.reaction)) / 2;
  return Math.round(clamp(base * (1 - m.interference * 0.4), 0, 100));
}

function scoreAttention(m: AttentionMetrics): number {
  const overallHit = (m.firstHalf.hitRate + m.secondHalf.hitRate) / 2;
  const inhibitAcc = m.inhibitShown > 0 ? 1 - m.inhibitErrors / m.inhibitShown : 1;
  const dropPenalty =
    (m.attentionDrop ? 0.15 : 0) +
    clamp(Math.max(0, m.rtDriftMs) / 400, 0, 0.15) +
    clamp(Math.max(0, m.stabilityDropMs) / 200, 0, 0.1);
  const raw = overallHit * 55 + inhibitAcc * 20 + 25 * (1 - clamp(dropPenalty / 0.4, 0, 1));
  return Math.round(clamp(raw, 0, 100));
}

/** 综合分数 0..100，由各模式指标加权得出 */
export function computeScore(metrics: ModeMetrics): number {
  switch (metrics.kind) {
    case "rhythm":
      return scoreRhythm(metrics);
    case "reaction":
      return scoreReaction(metrics);
    case "dual":
      return scoreDual(metrics);
    case "attention":
      return scoreAttention(metrics);
  }
}

