+/** Web Audio 节拍器：lookahead 调度，支持暂停/继续与音量控制 */
+
+export function isAudioSupported(): boolean {
+  return (
+    typeof window !== "undefined" &&
+    (typeof window.AudioContext !== "undefined" ||
+      typeof (window as unknown as { webkitAudioContext?: unknown }).webkitAudioContext !==
+        "undefined")
+  );
+}
+
+export class Metronome {
+  private ctx: AudioContext | null = null;
+  private gain: GainNode | null = null;
+  private timer: number | null = null;
+  /** performance.now() 时钟与 AudioContext 时钟的映射原点 */
+  private perfOriginMs = 0;
+  private nextBeatIndex = 0;
+  private schedule: { timeMs: number; accent: boolean }[] = [];
+  private startPerfMs = 0;
+  private running = false;
+  onBeatScheduled: ((index: number) => void) | null = null;
+
+  /** 返回 false 表示环境不支持 Web Audio */
+  init(volume: number): boolean {
+    if (!isAudioSupported()) return false;
+    if (!this.ctx) {
+      const Ctor =
+        window.AudioContext ??
+        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
+      this.ctx = new Ctor();
+      this.gain = this.ctx.createGain();
+      this.gain.connect(this.ctx.destination);
+    }
+    if (this.ctx.state === "suspended") void this.ctx.resume();
+    this.setVolume(volume);
+    return true;
+  }
+
+  setVolume(volume: number): void {
+    if (this.gain) this.gain.gain.value = Math.min(1, Math.max(0, volume));
+  }
+
+  /** 把 AudioContext 时间（秒）换算为 performance.now() 毫秒 */
+  ctxTimeToPerfMs(ctxTimeSec: number): number {
+    return this.perfOriginMs + ctxTimeSec * 1000;
+  }
+
+  nowPerfMs(): number {
+    return performance.now();
+  }
+
+  /**
+   * 开始按节拍计划播放。schedule 的 timeMs 是“相对 startPerfMs”的计划发声时刻。
