/** Web Audio 节拍器：lookahead 调度，支持暂停/继续与音量控制 */

export function isAudioSupported(): boolean {
  return (
    typeof window !== "undefined" &&
    (typeof window.AudioContext !== "undefined" ||
      typeof (window as unknown as { webkitAudioContext?: unknown }).webkitAudioContext !==
        "undefined")
  );
}

export class Metronome {
  private ctx: AudioContext | null = null;
  private gain: GainNode | null = null;
  private timer: number | null = null;
  /** performance.now() 时钟与 AudioContext 时钟的映射原点 */
  private perfOriginMs = 0;
  private nextBeatIndex = 0;
  private schedule: { timeMs: number; accent: boolean }[] = [];
  private startPerfMs = 0;
  private running = false;
  onBeatScheduled: ((index: number) => void) | null = null;

  /** 返回 false 表示环境不支持 Web Audio */
  init(volume: number): boolean {
    if (!isAudioSupported()) return false;
    if (!this.ctx) {
      const Ctor =
        window.AudioContext ??
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new Ctor();
      this.gain = this.ctx.createGain();
      this.gain.connect(this.ctx.destination);
    }
    if (this.ctx.state === "suspended") void this.ctx.resume();
    this.setVolume(volume);
    return true;
  }

  setVolume(volume: number): void {
    if (this.gain) this.gain.gain.value = Math.min(1, Math.max(0, volume));
  }

  /** 把 AudioContext 时间（秒）换算为 performance.now() 毫秒 */
  ctxTimeToPerfMs(ctxTimeSec: number): number {
    return this.perfOriginMs + ctxTimeSec * 1000;
  }

  nowPerfMs(): number {
    return performance.now();
  }

  /**
   * 开始按节拍计划播放。schedule 的 timeMs 是“相对 startPerfMs”的计划发声时刻。
   */
  start(schedule: { timeMs: number; accent: boolean }[], startPerfMs: number): void {
    if (!this.ctx) return;
    this.stop();
    this.schedule = schedule;
    this.startPerfMs = startPerfMs;
    this.perfOriginMs = performance.now() - this.ctx.currentTime * 1000;
    this.nextBeatIndex = 0;
    this.running = true;
    this.timer = window.setInterval(() => this.pump(), 25);
    this.pump();
  }

  private pump(): void {
    if (!this.ctx || !this.running) return;
    const nowPerf = performance.now();
    const lookaheadMs = 120;
    while (this.nextBeatIndex < this.schedule.length) {
      const beat = this.schedule[this.nextBeatIndex];
      const beatPerf = this.startPerfMs + beat.timeMs;
      if (beatPerf > nowPerf + lookaheadMs) break;
      const ctxTime = Math.max(
        this.ctx.currentTime + 0.005,
        (beatPerf - this.perfOriginMs) / 1000
      );
      this.click(ctxTime, beat.accent);
      this.onBeatScheduled?.(this.nextBeatIndex);
      this.nextBeatIndex++;
    }
    if (this.nextBeatIndex >= this.schedule.length) this.stopTimer();
  }

  private click(whenSec: number, accent: boolean): void {
    if (!this.ctx || !this.gain) return;
    const osc = this.ctx.createOscillator();
    const env = this.ctx.createGain();
    osc.frequency.value = accent ? 1568 : 1046;
    env.gain.setValueAtTime(0.0001, whenSec);
    env.gain.exponentialRampToValueAtTime(accent ? 1.0 : 0.7, whenSec + 0.004);
    env.gain.exponentialRampToValueAtTime(0.0001, whenSec + 0.09);
    osc.connect(env);
    env.connect(this.gain);
    osc.start(whenSec);
    osc.stop(whenSec + 0.1);
  }

  /** 立即播放一声测试音（用于设置页试听） */
  blip(): void {
    if (!this.ctx) return;
    this.click(this.ctx.currentTime + 0.02, true);
  }

  private stopTimer(): void {
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  stop(): void {
    this.running = false;
    this.stopTimer();
  }

  dispose(): void {
    this.stop();
    if (this.ctx) {
      void this.ctx.close();
      this.ctx = null;
      this.gain = null;
    }
  }
}

