import {
  DEFAULT_CALIBRATION,
  DEFAULT_SETTINGS,
  type CalibrationState,
  type DataIssue,
  type Profile,
  type Settings,
  type TestRecord,
} from "./types";

export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

export const KEYS = {
  settings: "rrt.settings.v1",
  profiles: "rrt.profiles.v1",
  activeProfile: "rrt.activeProfile.v1",
  calibration: "rrt.calibration.v1",
  records: "rrt.records.v1",
} as const;

const KEY_LABELS: Record<string, string> = {
  [KEYS.settings]: "设置",
  [KEYS.profiles]: "训练配置",
  [KEYS.activeProfile]: "当前配置",
  [KEYS.calibration]: "校准数据",
  [KEYS.records]: "测试记录",
};

const MAX_RECORDS = 50;

/**
 * 本地持久化层。所有读取都做了 JSON 解析保护：
 * 数据损坏时记录为 DataIssue，页面可提示用户“恢复默认”或“清空全部”。
 */
export class Store {
  private issues: DataIssue[] = [];

  constructor(private storage: StorageLike) {}

  getIssues(): DataIssue[] {
    return this.issues.slice();
  }

  private readJson<T>(key: string, fallback: T): T {
    let raw: string | null = null;
    try {
      raw = this.storage.getItem(key);
    } catch {
      return fallback;
    }
    if (raw === null) return fallback;
    try {
      return JSON.parse(raw) as T;
    } catch (err) {
      this.issues = this.issues.filter((i) => i.key !== key);
      this.issues.push({
        key,
        label: KEY_LABELS[key] ?? key,
        message: `本地数据损坏（${key}）：${err instanceof Error ? err.message : String(err)}`,
      });
      return fallback;
    }
  }

  private writeJson(key: string, value: unknown): boolean {
    try {
      this.storage.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false;
    }
  }

  /** 将损坏的键恢复为默认值 */
  repair(key: string): void {
    this.storage.removeItem(key);
    this.issues = this.issues.filter((i) => i.key !== key);
  }

  repairAll(): void {
    for (const issue of this.issues) this.storage.removeItem(issue.key);
    this.issues = [];
  }

  clearAll(): void {
    for (const key of Object.values(KEYS)) this.storage.removeItem(key);
    this.issues = [];
  }

  // ---- 设置 ----
  loadSettings(): Settings {
    const raw = this.readJson<Partial<Settings>>(KEYS.settings, {});
    return { ...DEFAULT_SETTINGS, ...raw };
  }

  saveSettings(s: Settings): boolean {
    return this.writeJson(KEYS.settings, s);
  }

  resetSettings(): Settings {
    this.storage.removeItem(KEYS.settings);
    return { ...DEFAULT_SETTINGS };
  }

  // ---- 训练配置 ----
  loadProfiles(): Profile[] {
    const list = this.readJson<Profile[]>(KEYS.profiles, []);
    return Array.isArray(list) ? list : [];
  }

  saveProfiles(list: Profile[]): boolean {
    return this.writeJson(KEYS.profiles, list);
  }

  loadActiveProfileId(): string | null {
    return this.readJson<string | null>(KEYS.activeProfile, null);
  }

  saveActiveProfileId(id: string | null): void {
    this.writeJson(KEYS.activeProfile, id);
  }

  // ---- 校准 ----
  loadCalibration(): CalibrationState {
    const raw = this.readJson<Partial<CalibrationState>>(KEYS.calibration, {});
    return { ...DEFAULT_CALIBRATION, ...raw, history: raw.history ?? [] };
  }

  saveCalibration(c: CalibrationState): boolean {
    return this.writeJson(KEYS.calibration, c);
  }

  // ---- 测试记录 ----
  loadRecords(): TestRecord[] {
    const list = this.readJson<TestRecord[]>(KEYS.records, []);
    return Array.isArray(list) ? list : [];
  }

  addRecord(rec: TestRecord): TestRecord[] {
    const list = this.loadRecords();
    list.unshift(rec);
    const trimmed = list.slice(0, MAX_RECORDS);
    this.writeJson(KEYS.records, trimmed);
    return trimmed;
  }

  deleteRecord(id: string): TestRecord[] {
    const list = this.loadRecords().filter((r) => r.id !== id);
    this.writeJson(KEYS.records, list);
    return list;
  }

  clearRecords(): void {
    this.storage.removeItem(KEYS.records);
  }
}

/** 浏览器环境默认 store */
export function createBrowserStore(): Store {
  return new Store(window.localStorage);
}

export function newId(): string {
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

