/** 极简 hash 路由，支持页面清理函数与导航守卫（测试中防止误触离开） */

export interface PageContext {
  params: Record<string, string>;
  query: URLSearchParams;
}

type PageFactory = (root: HTMLElement, ctx: PageContext) => void | (() => void);

interface Route {
  pattern: RegExp;
  keys: string[];
  factory: PageFactory;
}

const routes: Route[] = [];
let cleanup: (() => void) | null = null;
let navGuard: (() => boolean) | null = null;
let rootEl: HTMLElement | null = null;

export function registerRoute(path: string, factory: PageFactory): void {
  const keys: string[] = [];
  const pattern = new RegExp(
    "^" +
      path.replace(/:[^/]+/g, (m) => {
        keys.push(m.slice(1));
        return "([^/]+)";
      }) +
      "$"
  );
  routes.push({ pattern, keys, factory });
}

/** 测试进行中注册守卫：返回 false 表示阻止离开 */
export function setNavGuard(guard: (() => boolean) | null): void {
  navGuard = guard;
}

export function navigate(hash: string): void {
  if (navGuard && !navGuard()) return;
  window.location.hash = hash;
}

function render(): void {
  if (!rootEl) return;
  const raw = window.location.hash.slice(1) || "/";
  const [path, qs] = raw.split("?");
  for (const route of routes) {
    const m = route.pattern.exec(path);
    if (!m) continue;
    if (cleanup) {
      cleanup();
      cleanup = null;
    }
    rootEl.innerHTML = "";
    const params: Record<string, string> = {};
    route.keys.forEach((k, i) => (params[k] = decodeURIComponent(m[i + 1])));
    const result = route.factory(rootEl, { params, query: new URLSearchParams(qs ?? "") });
    if (typeof result === "function") cleanup = result;
    return;
  }
  // 未匹配路由回到首页
  window.location.hash = "/";
}

export function startRouter(root: HTMLElement): void {
  rootEl = root;
  window.addEventListener("hashchange", () => {
    if (navGuard && !navGuard()) return;
    render();
  });
  render();
}

