  --accent-2: #3ecf8e;
  --danger: #e5484d;
  --warn: #ffb020;
  --border: #2c3752;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
}

#app {
  max-width: 1080px;
  margin: 0 auto;
  padding: 20px 16px 60px;
}

h1, h2, h3 {
  margin: 0 0 12px;
}

.topnav {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 0 18px;
  flex-wrap: wrap;
}

.topnav .brand {
  font-weight: 700;
  font-size: 18px;
  color: var(--text);
  text-decoration: none;
  margin-right: auto;
}

.topnav a.navlink {
  color: var(--muted);
  text-decoration: none;
  padding: 6px 10px;
  border-radius: 8px;
}

.topnav a.navlink:hover {
  background: var(--panel-2);
  color: var(--text);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px;
  margin-bottom: 16px;
}

.grid {
  display: grid;
  gap: 14px;
}

.grid.cols-2 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid.cols-4 {
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
}

.card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 18px;
  cursor: pointer;
  transition: transform 0.12s ease, border-color 0.12s ease;
}

.card:hover {
  transform: translateY(-2px);
  border-color: var(--accent);
}

.card h3 {
  margin-bottom: 6px;
}

.muted {
  color: var(--muted);
  font-size: 13px;
}

.btn {
  border: 1px solid var(--border);
  background: var(--panel-2);
  color: var(--text);
  padding: 9px 16px;
  border-radius: 10px;
  font-size: 14px;
  cursor: pointer;
  transition: filter 0.12s ease;
}

.btn:hover {
  filter: brightness(1.15);
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.btn-success {
  background: var(--accent-2);
  border-color: var(--accent-2);
  color: #06251a;
}

.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}

.btn-ghost {
  background: transparent;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.row {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 14px;
}

.field label {
  display: block;
  font-size: 13px;
  color: var(--muted);
  margin-bottom: 5px;
}

.field input,
.field select {
  width: 100%;
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--text);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 14px;
}

.banner {
  border-radius: 10px;
  padding: 12px 14px;
  margin-bottom: 14px;
  font-size: 14px;
}

.banner-error {
  background: rgba(229, 72, 77, 0.15);
  border: 1px solid var(--danger);
}

.banner-warn {
  background: rgba(255, 176, 32, 0.12);
  border: 1px solid var(--warn);
}

.banner-info {
  background: rgba(79, 140, 255, 0.12);
  border: 1px solid var(--accent);
}

table.data {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

table.data th,
table.data td {
  text-align: left;
  padding: 8px 10px;
  border-bottom: 1px solid var(--border);
}

table.data th {
  color: var(--muted);
  font-weight: 500;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 12px;
}

.metric {
  background: var(--panel-2);
  border-radius: 10px;
  padding: 12px;
}

.metric .value {
  font-size: 22px;
  font-weight: 700;
}

.metric .label {
  font-size: 12px;
  color: var(--muted);
  margin-top: 2px;
}

.score-big {
  font-size: 52px;
  font-weight: 800;
  color: var(--accent-2);
}

/* 测试舞台 */
.stage-wrap {
  position: relative;
}

.stage {
  position: relative;
  width: 100%;
  height: min(56vh, 520px);
  min-height: 320px;
  background: #0b0f1a;
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  user-select: none;
  touch-action: none;
}

.hud {
  display: flex;
  gap: 18px;
  align-items: center;
  padding: 10px 4px;
  flex-wrap: wrap;
  font-variant-numeric: tabular-nums;
}

.hud .hud-item {
  font-size: 14px;
  color: var(--muted);
}

.hud .hud-item b {
  color: var(--text);
  font-size: 16px;
}

.progress-track {
  flex: 1 1 160px;
  height: 8px;
  background: var(--panel-2);
  border-radius: 4px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--accent);
  width: 0%;
  transition: width 0.2s linear;
}

.target {
  position: absolute;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: #fff;
  box-shadow: 0 0 18px rgba(255, 255, 255, 0.25);
}

.target.inhibit {
  border-radius: 8px;
  font-size: 24px;
}

.beat-ring {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 3px solid var(--accent);
  pointer-events: none;
}

.beat-core {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46px;
  height: 46px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: rgba(79, 140, 255, 0.25);
  border: 2px solid var(--accent);
  pointer-events: none;
}

.tap-flash {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  pointer-events: none;
  animation: tapflash 0.35s ease-out forwards;
}

@keyframes tapflash {
  from {
    opacity: 0.9;
    width: 30px;
    height: 30px;
  }
  to {
    opacity: 0;
    width: 120px;
    height: 120px;
  }
}

.countdown-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(11, 15, 26, 0.85);
  font-size: 84px;
  font-weight: 800;
  z-index: 5;
}

.pause-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  justify-content: center;
  background: rgba(11, 15, 26, 0.9);
  z-index: 6;
}

.combo-pop {
  position: absolute;
  left: 50%;
  top: 30%;
  transform: translateX(-50%);
  font-size: 28px;
  font-weight: 800;
  color: var(--warn);
  pointer-events: none;
}

.hist-chart {
  display: flex;
  align-items: flex-end;
  gap: 4px;
  height: 110px;
  padding: 8px;
  background: var(--panel-2);
  border-radius: 10px;
}

.hist-bar {
  flex: 1;
  background: var(--accent);
  border-radius: 3px 3px 0 0;
  min-height: 2px;
  position: relative;
}

.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--panel-2);
  border: 1px solid var(--border);
  padding: 10px 18px;
  border-radius: 10px;
  opacity: 0;
  transition: all 0.25s ease;
  z-index: 100;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.toast-error {
  border-color: var(--danger);
}

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 90;
}

.modal {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 22px;
  width: min(420px, 90vw);
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 16px;
}

.tag {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 12px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  color: var(--muted);
}

.suggestion-list li {
  margin-bottom: 6px;
}

@media (max-width: 640px) {
  #app {
    padding: 12px 10px 48px;
  }
  .stage {
    height: 52vh;
  }
  .countdown-overlay {
    font-size: 56px;
  }
}

