import type { TestRecord } from "./types";

/** 当前会话内最近一次测试结果（结果页数据源） */
let lastResult: TestRecord | null = null;
let lastSaved = false;

export function setLastResult(rec: TestRecord): void {
  lastResult = rec;
  lastSaved = false;
  try {
    sessionStorage.setItem("rrt.lastResult", JSON.stringify(rec));
  } catch {
    /* 忽略 */
  }
}

export function getLastResult(): TestRecord | null {
  if (lastResult) return lastResult;
  try {
    const raw = sessionStorage.getItem("rrt.lastResult");
    if (raw) lastResult = JSON.parse(raw) as TestRecord;
  } catch {
    lastResult = null;
  }
  return lastResult;
}

export function isLastSaved(): boolean {
  return lastSaved;
}

export function markLastSaved(): void {
  lastSaved = true;
}

/** 记录页查看历史详情时复用结果页 */
export function viewRecord(rec: TestRecord): void {
  lastResult = rec;
  lastSaved = true;
}

