import { navigate } from "../router";
import type { Store } from "../store";
import { KEYS } from "../store";
import { isAudioSupported } from "../core/audio";
import { btn, el } from "../ui";

export interface AppCtx {
  store: Store;
}

export function renderNav(root: HTMLElement, active: string): void {
  const nav = el(
    "div",
    { className: "topnav" },
    el("a", { className: "brand", href: "#/" }, "⚡ 节奏与反应训练")
  );
  const links: [string, string, string][] = [
    ["/", "开始", "home"],
    ["/settings", "设置", "settings"],
    ["/calibration", "延迟校准", "calibration"],
    ["/tests", "测试", "tests"],
    ["/records", "记录", "records"],
  ];
  for (const [href, label, key] of links) {
    const a = el("a", { className: "navlink", href: `#${href}` }, label);
    if (key === active) a.style.color = "var(--text)";
    nav.appendChild(a);
  }
  root.appendChild(nav);
}

/** 数据损坏提示条：提供“恢复默认”和“清空全部” */
export function renderIssueBanner(root: HTMLElement, ctx: AppCtx): void {
  const issues = ctx.store.getIssues();
  if (issues.length === 0) return;
  const banner = el("div", { className: "banner banner-error" });
  banner.appendChild(el("b", {}, "检测到本地数据损坏："));
  const ul = el("ul", { style: "margin:6px 0" });
  for (const issue of issues) {
    ul.appendChild(el("li", {}, `${issue.label} — ${issue.message}`));
  }
  banner.appendChild(ul);
  banner.appendChild(
    el(
      "div",
      { className: "row" },
      btn("恢复损坏项为默认", "btn", () => {
        for (const issue of issues) ctx.store.repair(issue.key);
        window.location.reload();
      }),
      btn("清空全部本地数据", "btn btn-danger", () => {
        ctx.store.clearAll();
        window.location.reload();
      })
    )
  );
  root.appendChild(banner);
}

export function renderAudioWarning(root: HTMLElement): void {
  if (isAudioSupported()) return;
  root.appendChild(
    el(
      "div",
      { className: "banner banner-warn" },
      "当前浏览器不支持 Web Audio API，无法播放节拍声音。建议：使用最新版 Chrome / Edge / Firefox；",
      "在没有音频的环境下仍可进行视觉反应与持续注意测试（节奏类测试将只有视觉提示）。"
    )
  );
}

export function pageContainer(root: HTMLElement, active: string, ctx: AppCtx): HTMLElement {
  renderNav(root, active);
  renderIssueBanner(root, ctx);
  renderAudioWarning(root);
  const main = el("div", {});
  root.appendChild(main);
  return main;
}

export { navigate, KEYS };

