import { Metronome } from "../core/audio";
import { newId } from "../store";
import { DEFAULT_SETTINGS, type Profile, type Settings } from "../types";
import { btn, clear, confirmDialog, el, toast } from "../ui";
import { pageContainer, type AppCtx } from "./layout";

export function settingsPage(root: HTMLElement, ctx: AppCtx): void {
  const main = pageContainer(root, "settings", ctx);
  const settings = ctx.store.loadSettings();
  main.appendChild(el("h2", {}, "训练设置"));

  const panel = el("div", { className: "panel" });
  const grid = el("div", { className: "form-grid" });

  const save = () => {
    if (ctx.store.saveSettings(settings)) toast("设置已保存");
    else toast("保存失败：本地存储不可用", "error");
  };

  const hintEl = (text: string) =>
    text ? el("div", { className: "muted", style: "margin-top:4px" }, text) : el("span", {});

  function numberField(
    label: string,
    key: keyof Settings,
    min: number,
    max: number,
    step = 1,
    hint = ""
  ): HTMLElement {
    const input = document.createElement("input");
    input.type = "number";
    input.min = String(min);
    input.max = String(max);
    input.step = String(step);
    input.value = String(settings[key]);
    input.addEventListener("change", () => {
      const v = Number(input.value);
      if (Number.isFinite(v)) {
        (settings[key] as number) = Math.min(max, Math.max(min, v));
        input.value = String(settings[key]);
        save();
      }
    });
    return el("div", { className: "field" }, el("label", {}, label), input, hintEl(hint));
  }

  function selectField<K extends keyof Settings>(
    label: string,
    key: K,
    options: [string, string][]
  ): HTMLElement {
    const select = document.createElement("select");
    for (const [value, text] of options) {
      const opt = document.createElement("option");
      opt.value = value;
      opt.textContent = text;
      select.appendChild(opt);
    }
    select.value = String(settings[key]);
    select.addEventListener("change", () => {
      (settings[key] as Settings[K]) = select.value as Settings[K];
      save();
    });
    return el("div", { className: "field" }, el("label", {}, label), select);
  }

  grid.appendChild(
    numberField("音频输出延迟 (ms)", "audioLatencyMs", -500, 500, 1, "由校准自动填写，也可手动微调")
  );
  grid.appendChild(
    numberField("输入延迟补偿 (ms)", "inputLatencyMs", -500, 500, 1, "正值表示从敲击时间中扣除的延迟")
  );
  grid.appendChild(numberField("BPM（节拍速度）", "bpm", 40, 240));
  grid.appendChild(
    selectField("节拍细分", "subdivision", [
      ["1", "四分音符"],
      ["2", "八分音符"],
      ["4", "十六分音符"],
    ])
  );
  grid.appendChild(numberField("测试时长 (秒)", "durationSec", 10, 600));
  grid.appendChild(
    selectField("难度", "difficulty", [
      ["easy", "简单"],
      ["medium", "中等"],
      ["hard", "困难"],
    ])
  );
  grid.appendChild(
    selectField("输入设备", "inputDevice", [
      ["keyboard", "键盘（空格 / F）"],
      ["mouse", "鼠标（点击）"],
    ])
  );

  const volumeInput = document.createElement("input");
  volumeInput.type = "range";
  volumeInput.min = "0";
  volumeInput.max = "1";
  volumeInput.step = "0.05";
  volumeInput.value = String(settings.volume);
  volumeInput.addEventListener("change", () => {
    settings.volume = Number(volumeInput.value);
    save();
  });
  grid.appendChild(el("div", { className: "field" }, el("label", {}, "音量"), volumeInput));

  panel.appendChild(grid);

  const metronome = new Metronome();
  panel.appendChild(
    el(
      "div",
      { className: "row", style: "margin-top:16px" },
      btn("试听节拍音", "btn", () => {
        if (!metronome.init(settings.volume)) {
          toast("当前浏览器不支持 Web Audio", "error");
          return;
        }
        metronome.setVolume(settings.volume);
        metronome.blip();
      }),
      btn("恢复默认设置", "btn btn-ghost", async () => {
        if (await confirmDialog("恢复默认", "确定要将所有设置恢复为默认值吗？")) {
          Object.assign(settings, ctx.store.resetSettings(), DEFAULT_SETTINGS);
          toast("已恢复默认设置");
          rerender();
        }
      }),
      btn("清空本地数据", "btn btn-danger", async () => {
        if (
          await confirmDialog(
            "清空本地数据",
            "将删除设置、训练配置、校准数据与全部测试记录，且不可恢复。确定继续吗？",
            "全部清空"
          )
        ) {
          ctx.store.clearAll();
          toast("本地数据已清空");
          window.location.reload();
        }
      })
    )
  );
  main.appendChild(panel);

  const profilePanel = el("div", { className: "panel" });
  profilePanel.appendChild(el("h3", {}, "训练配置（可保存多组，用于重复相同测试）"));
  const nameInput = document.createElement("input");
  nameInput.placeholder = "配置名称，例如：120BPM 键盘中等";
  nameInput.style.maxWidth = "280px";
  const listEl = el("div", {});

  function renderProfiles(): void {
    clear(listEl);
    const profiles = ctx.store.loadProfiles();
    const activeId = ctx.store.loadActiveProfileId();
    if (profiles.length === 0) {
      listEl.appendChild(el("p", { className: "muted" }, "暂无已保存的配置。"));
      return;
    }
    const table = el("table", { className: "data" });
    table.appendChild(el("tr", {}, el("th", {}, "名称"), el("th", {}, "参数"), el("th", {}, "操作")));
    for (const p of profiles) {
      const s = p.settings;
      const tr = el(
        "tr",
        {},
        el(
          "td",
          {},
          p.name,
          p.id === activeId
            ? el("span", { className: "tag", style: "margin-left:8px" }, "当前使用")
            : ""
        ),
        el(
          "td",
          { className: "muted" },
          `${s.bpm}BPM · ${s.difficulty} · ${s.durationSec}s · ${
            s.inputDevice === "keyboard" ? "键盘" : "鼠标"
          }`
        ),
        el(
          "td",
          {},
          el(
            "div",
            { className: "row" },
            btn("应用", "btn", () => {
              ctx.store.saveSettings({ ...p.settings });
              ctx.store.saveActiveProfileId(p.id);
              toast(`已应用配置「${p.name}」`);
              rerender();
            }),
            btn("删除", "btn btn-ghost", async () => {
              if (await confirmDialog("删除配置", `确定删除配置「${p.name}」吗？`)) {
                ctx.store.saveProfiles(ctx.store.loadProfiles().filter((x) => x.id !== p.id));
                if (ctx.store.loadActiveProfileId() === p.id) ctx.store.saveActiveProfileId(null);
                renderProfiles();
              }
            })
          )
        )
      );
      table.appendChild(tr);
    }
    listEl.appendChild(table);
  }

  profilePanel.appendChild(
    el(
      "div",
      { className: "row", style: "margin-bottom:12px" },
      nameInput,
      btn("保存当前设置为配置", "btn btn-primary", () => {
        const name = nameInput.value.trim();
        if (!name) {
          toast("请先填写配置名称", "error");
          return;
        }
        const profiles = ctx.store.loadProfiles();
        const profile: Profile = {
          id: newId(),
          name,
          settings: { ...settings },
          createdAt: Date.now(),
        };
        profiles.push(profile);
        ctx.store.saveProfiles(profiles);
        ctx.store.saveActiveProfileId(profile.id);
        nameInput.value = "";
        toast(`配置「${name}」已保存并设为当前配置`);
        renderProfiles();
      })
    )
  );
  profilePanel.appendChild(listEl);
  main.appendChild(profilePanel);

  function rerender(): void {
    root.innerHTML = "";
    settingsPage(root, ctx);
  }

  renderProfiles();
}

