import { Metronome, isAudioSupported } from "../core/audio";
import { estimateLatencyFromOffsets } from "../core/timing";
import { newId } from "../store";
import type { CalibrationRecord } from "../types";
import { btn, clear, el, fmtMs, fmtTime, toast } from "../ui";
import { pageContainer, type AppCtx } from "./layout";

type Phase = "combined" | "visual";

interface PhaseResult {
  phase: Phase;
  bpm: number;
  offsets: number[];
  durationMs: number;
}

const PHASE_BEATS: Record<Phase, number> = { combined: 16, visual: 12 };

export function calibrationPage(root: HTMLElement, ctx: AppCtx): void {
  const main = pageContainer(root, "calibration", ctx);
  main.appendChild(el("h2", {}, "延迟校准"));
  main.appendChild(
    el(
      "p",
      { className: "muted" },
      "第一阶段跟随“声音+闪光”敲击，测得综合延迟（音频输出 + 输入）；第二阶段只跟随闪光敲击，测得输入延迟。两者相减得到音频输出延迟。校准结果保存后会自动用于后续测试的时间补偿。"
    )
  );

  if (!isAudioSupported()) {
    main.appendChild(
      el(
        "div",
        { className: "banner banner-warn" },
        "当前浏览器不支持 Web Audio，无法播放校准节拍声。可改用“仅视觉”阶段估算输入延迟，",
        "或换用最新版 Chrome / Edge / Firefox 完成完整校准。"
      )
    );
  }

  let bpm = 120;
  const bpmSelect = document.createElement("select");
  for (const b of [60, 120, 240]) {
    const opt = document.createElement("option");
    opt.value = String(b);
    opt.textContent = `${b} BPM`;
    bpmSelect.appendChild(opt);
  }
  bpmSelect.value = "120";
  bpmSelect.addEventListener("change", () => (bpm = Number(bpmSelect.value)));

  const statusEl = el("div", { className: "muted" }, "选择 BPM 后点击开始。");
  const stage = el("div", { className: "stage", style: "height:300px;min-height:260px" });
  const core = el("div", { className: "beat-core" });
  stage.appendChild(core);
  const tapList = el("div", { className: "muted", style: "margin-top:8px;min-height:20px" });

  const startBtn = btn("开始校准", "btn btn-primary", () => startCalibration());
  main.appendChild(
    el(
      "div",
      { className: "panel" },
      el("div", { className: "row", style: "margin-bottom:12px" }, el("span", {}, "校准速度："), bpmSelect, startBtn),
      statusEl,
      el("div", { className: "stage-wrap", style: "margin-top:12px" }, stage),
      tapList
    )
  );

  const resultPanel = el("div", { className: "panel", style: "display:none" });
  main.appendChild(resultPanel);

  const historyPanel = el("div", { className: "panel" });
  main.appendChild(historyPanel);

  function renderHistory(): void {
    clear(historyPanel);
    historyPanel.appendChild(el("h3", {}, "校准记录"));
    const cal = ctx.store.loadCalibration();
    if (cal.audioLatencyMs !== null || cal.inputLatencyMs !== null) {
      historyPanel.appendChild(
        el(
          "p",
          {},
          `当前生效补偿：音频输出延迟 ${fmtMs(cal.audioLatencyMs)}，输入延迟 ${fmtMs(
            cal.inputLatencyMs
          )}`,
          cal.updatedAt ? `（更新于 ${fmtTime(cal.updatedAt)}）` : ""
        )
      );
    }
    if (cal.history.length === 0) {
      historyPanel.appendChild(el("p", { className: "muted" }, "暂无校准记录。"));
      return;
    }
    const table = el("table", { className: "data" });
    table.appendChild(
      el(
        "tr",
        {},
        el("th", {}, "时间"),
        el("th", {}, "BPM"),
        el("th", {}, "阶段"),
        el("th", {}, "敲击数"),
        el("th", {}, "平均偏差"),
        el("th", {}, "标准差"),
        el("th", {}, "用时")
      )
    );
    for (const rec of cal.history.slice(0, 10)) {
      table.appendChild(
        el(
          "tr",
          {},
          el("td", {}, fmtTime(rec.completedAt)),
          el("td", {}, String(rec.bpm)),
          el("td", {}, rec.phase === "combined" ? "声画同步" : "仅视觉"),
          el("td", {}, String(rec.tapCount)),
          el("td", {}, fmtMs(rec.meanOffsetMs, 1)),
          el("td", {}, fmtMs(rec.stdMs, 1)),
          el("td", {}, `${(rec.durationMs / 1000).toFixed(1)}s`)
        )
      );
    }
    historyPanel.appendChild(table);
  }

  function startCalibration(): void {
    startBtn.disabled = true;
    bpmSelect.disabled = true;
    const phases: Phase[] = isAudioSupported() ? ["combined", "visual"] : ["visual"];
    const results: PhaseResult[] = [];
    let phaseIdx = 0;

    const runPhase = () => {
      const phase = phases[phaseIdx];
      runPhaseEngine(phase, bpm, (result) => {
        results.push(result);
        savePhaseRecord(result);
        phaseIdx++;
        if (phaseIdx < phases.length) {
          statusEl.textContent = "第一阶段完成，3 秒后开始仅视觉阶段…";
          setTimeout(runPhase, 3000);
        } else {
          finishCalibration(results);
        }
      });
    };
    runPhase();
  }

  function runPhaseEngine(phase: Phase, bpmValue: number, done: (r: PhaseResult) => void): void {
    const beatCount = PHASE_BEATS[phase];
    const interval = 60000 / bpmValue;
    const withSound = phase === "combined" && isAudioSupported();
    const settings = ctx.store.loadSettings();
    const metronome = new Metronome();
    const offsets: number[] = [];
    let raf = 0;
    let finished = false;

    statusEl.textContent =
      phase === "combined"
        ? `阶段 1/2：跟随声音+闪光敲击（${bpmValue} BPM，共 ${beatCount} 拍）`
        : `阶段 2/2：只跟随闪光敲击（${bpmValue} BPM，共 ${beatCount} 拍）`;

    const countdownEl = el("div", { className: "countdown-overlay" }, "3");
    stage.appendChild(countdownEl);
    let count = 3;
    const countTimer = setInterval(() => {
      count--;
      if (count <= 0) {
        clearInterval(countTimer);
        countdownEl.remove();
        begin();
      } else {
        countdownEl.textContent = String(count);
      }
    }, 700);

    const begin = () => {
      const startPerf = performance.now() + 50;
      const beatTimes = Array.from({ length: beatCount }, (_, i) => startPerf + 800 + i * interval);
      if (withSound && metronome.init(settings.volume)) {
        metronome.start(
          beatTimes.map((t, i) => ({ timeMs: t - startPerf, accent: i % 4 === 0 })),
          startPerf
        );
      }
      const onInput = (e: Event) => {
        if (finished) return;
        if (e instanceof KeyboardEvent && e.code !== "Space" && e.code !== "KeyF") return;
        if (e instanceof KeyboardEvent) e.preventDefault();
        const now = performance.now();
        let best: number | null = null;
        for (const bt of beatTimes) {
          const off = now - bt;
          if (Math.abs(off) <= 400 && (best === null || Math.abs(off) < Math.abs(best))) best = off;
        }
        if (best !== null) {
          offsets.push(best);
          tapList.textContent = `第 ${offsets.length} 次敲击：偏差 ${best.toFixed(0)}ms`;
          flash(best);
        }
      };
      window.addEventListener("keydown", onInput);
      stage.addEventListener("pointerdown", onInput);

      const flash = (offset: number) => {
        const f = el("div", { className: "tap-flash" });
        f.style.border = `3px solid ${Math.abs(offset) <= 80 ? "var(--accent-2)" : "var(--warn)"}`;
        stage.appendChild(f);
        setTimeout(() => f.remove(), 400);
      };

      const tick = () => {
        const now = performance.now();
        const next = beatTimes.find((t) => t >= now - 60);
        if (next !== undefined && now >= next - 60 && now <= next + 120) {
          core.style.background = "rgba(62, 207, 142, 0.8)";
        } else {
          core.style.background = "rgba(79, 140, 255, 0.25)";
        }
        if (now > beatTimes[beatTimes.length - 1] + 800) {
          finished = true;
          cancelAnimationFrame(raf);
          window.removeEventListener("keydown", onInput);
          stage.removeEventListener("pointerdown", onInput);
          metronome.dispose();
          core.style.background = "rgba(79, 140, 255, 0.25)";
          done({
            phase,
            bpm: bpmValue,
            offsets,
            durationMs: now - startPerf,
          });
          return;
        }
        raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    };
  }

  function savePhaseRecord(result: PhaseResult): void {
    const est = estimateLatencyFromOffsets(result.offsets);
    const cal = ctx.store.loadCalibration();
    const rec: CalibrationRecord = {
      id: newId(),
      bpm: result.bpm,
      phase: result.phase,
      offsetsMs: result.offsets.map((v) => Math.round(v * 10) / 10),
      meanOffsetMs: est.meanMs,
      stdMs: est.stdMs,
      tapCount: result.offsets.length,
      durationMs: result.durationMs,
      completedAt: Date.now(),
    };
    cal.history.unshift(rec);
    cal.history = cal.history.slice(0, 30);
    if (result.phase === "combined") cal.combinedMeanMs = est.meanMs;
    else cal.visualMeanMs = est.meanMs;
    ctx.store.saveCalibration(cal);
  }

  function finishCalibration(results: PhaseResult[]): void {
    startBtn.disabled = false;
    bpmSelect.disabled = false;
    statusEl.textContent = "校准完成。";
    const combined = results.find((r) => r.phase === "combined");
    const visual = results.find((r) => r.phase === "visual");
    const combinedEst = combined ? estimateLatencyFromOffsets(combined.offsets) : null;
    const visualEst = visual ? estimateLatencyFromOffsets(visual.offsets) : null;

    let audioLatency: number | null = null;
    let inputLatency: number | null = null;
    if (combinedEst && visualEst) {
      inputLatency = visualEst.meanMs;
      audioLatency = Math.max(0, combinedEst.meanMs - visualEst.meanMs);
    } else if (visualEst) {
      inputLatency = visualEst.meanMs;
    }

    clear(resultPanel);
    resultPanel.style.display = "";
    resultPanel.appendChild(el("h3", {}, "校准结果"));
    const grid = el("div", { className: "metric-grid" });
    if (combinedEst) {
      grid.appendChild(metric("综合延迟（声画）", fmtMs(combinedEst.meanMs, 1)));
      grid.appendChild(metric("声画阶段标准差", fmtMs(combinedEst.stdMs, 1)));
    }
    if (visualEst) {
      grid.appendChild(metric("输入延迟（视觉）", fmtMs(visualEst.meanMs, 1)));
      grid.appendChild(metric("视觉阶段标准差", fmtMs(visualEst.stdMs, 1)));
    }
    if (audioLatency !== null) grid.appendChild(metric("估算音频输出延迟", fmtMs(audioLatency, 1)));
    resultPanel.appendChild(grid);

    const tooFew = results.some((r) => r.offsets.length < 6);
    if (tooFew) {
      resultPanel.appendChild(
        el("div", { className: "banner banner-warn", style: "margin-top:12px" }, "有效敲击次数较少，结果可能不可靠，建议重新校准。")
      );
    }
    resultPanel.appendChild(
      el(
        "div",
        { className: "row", style: "margin-top:14px" },
        btn("保存并应用到设置", "btn btn-success", () => {
          const cal = ctx.store.loadCalibration();
          cal.audioLatencyMs = audioLatency;
          cal.inputLatencyMs = inputLatency;
          cal.updatedAt = Date.now();
          ctx.store.saveCalibration(cal);
          const settings = ctx.store.loadSettings();
          if (audioLatency !== null) settings.audioLatencyMs = Math.round(audioLatency);
          if (inputLatency !== null) settings.inputLatencyMs = Math.round(inputLatency);
          ctx.store.saveSettings(settings);
          toast("校准结果已保存并应用到设置");
          renderHistory();
        }),
        btn("重新校准", "btn btn-ghost", () => {
          resultPanel.style.display = "none";
          startCalibration();
        })
      )
    );
    renderHistory();
  }

  function metric(label: string, value: string): HTMLElement {
    return el("div", { className: "metric" }, el("div", { className: "value" }, value), el("div", { className: "label" }, label));
  }

  renderHistory();
}

