import { Metronome } from "../core/audio";
import { mean, std } from "../core/stats";
import { generateBeatPlan, type BeatEvent } from "../core/targets";
import {
  computeOffsetMs,
  hitWindowMs,
  isHit,
  rhythmBias,
  stabilityFromStd,
} from "../core/timing";
import type { RhythmMetrics } from "../types";
import { el } from "../ui";
import { startPerfNow, type Engine, type EngineDeps } from "./common";

type BeatState = "pending" | "hit" | "missed";

/** 节奏跟随引擎：节拍调度、视觉收缩环提示、敲击判定 */
export class RhythmEngine implements Engine {
  protected beats: BeatEvent[];
  protected states: BeatState[];
  protected offsets: number[] = [];
  protected hits = 0;
  protected misses = 0;
  protected wrongTaps = 0;
  protected combo = 0;
  protected maxCombo = 0;
  protected metronome: Metronome | null = null;
  protected ring: HTMLElement;
  protected core: HTMLElement;
  protected finished = false;
  protected windowMs: number;

  constructor(protected deps: EngineDeps) {
    this.beats = generateBeatPlan(
      deps.durationMs,
      deps.settings.bpm,
      deps.settings.subdivision,
      deps.seed
    );
    this.states = this.beats.map(() => "pending");
    this.windowMs = hitWindowMs(deps.settings.difficulty);
    this.ring = el("div", { className: "beat-ring" });
    this.core = el("div", { className: "beat-core" });
    deps.stage.appendChild(this.ring);
    deps.stage.appendChild(this.core);
    this.startAudio();
  }

  protected startAudio(): void {
    const { settings } = this.deps;
    if (!this.metronome) this.metronome = new Metronome();
    if (!this.metronome.init(settings.volume)) return;
    const elapsed = this.deps.getElapsed();
    const remaining = this.beats
      .filter((b, i) => this.states[i] === "pending" && b.timeMs > elapsed - 50)
      .map((b) => ({ timeMs: b.timeMs, accent: b.accent }));
    this.metronome.start(remaining, performance.now() - elapsed);
  }

  update(): void {
    if (this.finished) return;
    const elapsed = this.deps.getElapsed();
    for (let i = 0; i < this.beats.length; i++) {
      if (this.states[i] === "pending" && this.beats[i].timeMs + this.windowMs < elapsed) {
        this.states[i] = "missed";
        this.misses++;
        this.combo = 0;
      }
    }
    const next = this.beats.find(
      (b, i) => this.states[i] === "pending" && b.timeMs >= elapsed - 100
    );
    if (next) {
      const lead = 500;
      const dt = next.timeMs - elapsed;
      if (dt <= lead) {
        const p = Math.max(0, dt / lead);
        const size = 46 + p * 150;
        this.ring.style.width = `${size}px`;
        this.ring.style.height = `${size}px`;
        this.ring.style.borderColor = next.color;
        this.ring.style.opacity = "1";
      } else {
        this.ring.style.opacity = "0.25";
        this.ring.style.width = "196px";
        this.ring.style.height = "196px";
      }
      this.core.style.borderColor = next.color;
    } else {
      this.ring.style.opacity = "0";
    }
    this.deps.setHud({
      命中: String(this.hits),
      漏拍: String(this.misses),
      连击: String(this.combo),
    });
    if (elapsed >= this.deps.durationMs && this.states.every((s) => s !== "pending")) {
      this.finish();
    }
  }

  protected tap(): void {
    if (this.finished) return;
    const { settings } = this.deps;
    const startPerf = startPerfNow(this.deps);
    const now = performance.now();
    let bestIdx = -1;
    let bestOffset = Infinity;
    for (let i = 0; i < this.beats.length; i++) {
      if (this.states[i] !== "pending") continue;
      const off = computeOffsetMs(
        now,
        startPerf + this.beats[i].timeMs,
        settings.audioLatencyMs,
        settings.inputLatencyMs
      );
      if (Math.abs(off) < Math.abs(bestOffset)) {
        bestOffset = off;
        bestIdx = i;
      }
    }
    if (bestIdx === -1 || Math.abs(bestOffset) > 300) {
      this.wrongTaps++;
      this.combo = 0;
      this.flashTap("var(--danger)");
      return;
    }
    if (isHit(bestOffset, this.windowMs)) {
      this.states[bestIdx] = "hit";
      this.hits++;
      this.offsets.push(bestOffset);
      this.combo++;
      this.maxCombo = Math.max(this.maxCombo, this.combo);
      this.flashTap("var(--accent-2)");
    } else {
      this.wrongTaps++;
      this.combo = 0;
      this.flashTap("var(--warn)");
    }
  }

  private flashTap(color: string): void {
    const f = el("div", { className: "tap-flash" });
    f.style.border = `3px solid ${color}`;
    this.deps.stage.appendChild(f);
    setTimeout(() => f.remove(), 400);
  }

  onPointer(): void {
    if (this.deps.settings.inputDevice === "mouse") this.tap();
  }

  onKey(code: string): void {
    if (this.deps.settings.inputDevice === "keyboard" && code === "Space") this.tap();
  }

  pause(): void {
    this.metronome?.stop();
  }

  resume(): void {
    this.startAudio();
  }

  protected buildMetrics(): RhythmMetrics {
    const total = this.beats.length;
    return {
      kind: "rhythm",
      totalBeats: total,
      hits: this.hits,
      misses: this.misses,
      wrongTaps: this.wrongTaps,
      hitRate: total > 0 ? this.hits / total : 0,
      meanOffsetMs: mean(this.offsets),
      stdOffsetMs: std(this.offsets),
      fastestOffsetMs:
        this.offsets.length > 0
          ? this.offsets.reduce((a, b) => (Math.abs(a) <= Math.abs(b) ? a : b))
          : 0,
      maxCombo: this.maxCombo,
      stability: stabilityFromStd(std(this.offsets)),
      bias: rhythmBias(mean(this.offsets)),
    };
  }

  protected finish(): void {
    if (this.finished) return;
    this.finished = true;
    this.metronome?.stop();
    this.deps.onFinish(this.buildMetrics());
  }

  destroy(): void {
    this.metronome?.dispose();
    this.ring.remove();
    this.core.remove();
  }
}

