    while (this.spawned < this.plan.length && this.plan[this.spawned].appearAtMs <= elapsed) {
      this.spawnTarget(this.plan[this.spawned]);
      this.spawned++;
    }
    for (const [id, t] of Array.from(this.active)) {
      if (elapsed > t.event.appearAtMs + t.event.lifetimeMs) {
        this.expireTarget(id, t);
      }
    }
    this.deps.setHud({
      命中: String(this.hits),
      漏点: String(this.misses),
      误触: String(this.falseClicks),
    });
    if (elapsed >= this.deps.durationMs && this.active.size === 0 && this.spawned >= this.plan.length) {
      this.finish();
    }
  }

  protected expireTarget(id: number, t: ActiveTarget): void {
    t.node.remove();
    this.active.delete(id);
    if (t.event.inhibit) {
      // 成功抑制：不点干扰目标，不计漏点
    } else {
      this.misses++;
    }
  }

  protected hitTarget(t: ActiveTarget): void {
    const rt = computeReactionMs(
      performance.now(),
      t.shownAtPerf,
      this.deps.settings.inputLatencyMs
    );
    if (t.event.inhibit) {
      this.onInhibitClicked?.(t);
    } else {
      this.rts.push(rt);
      this.hits++;
    }
    t.node.remove();
    this.active.delete(t.event.id);
  }

  /** 持续注意测试覆盖此方法统计抑制错误 */
  protected onInhibitClicked?: (t: ActiveTarget) => void;

  onPointer(_x: number, _y: number, target: HTMLElement | null): void {
    if (this.deps.settings.inputDevice !== "mouse" || this.finished) return;
    const node = target?.closest(".target") as HTMLElement | null;
    if (node && node.dataset.targetId !== undefined) {
      const t = this.active.get(Number(node.dataset.targetId));
      if (t) {
        this.hitTarget(t);
        return;
      }
    }
    this.falseClicks++;
  }

  onKey(): void {
    if (this.deps.settings.inputDevice !== "keyboard" || this.finished) return;
    const first = Array.from(this.active.values()).sort(
      (a, b) => a.event.appearAtMs - b.event.appearAtMs
    )[0];
    if (first) this.hitTarget(first);
    else this.falseClicks++;
  }

  pause(): void {
    /* 视觉目标由主循环驱动，暂停时主循环停止即可 */
  }

  resume(): void {
    /* 同上 */
  }

  protected buildMetrics(): ReactionMetrics {
    const shown = this.plan.filter((e) => !e.inhibit).length;
    return {
      kind: "reaction",
      targetsShown: shown,
      hits: this.hits,
      misses: this.misses,
      falseClicks: this.falseClicks,
      hitRate: shown > 0 ? this.hits / shown : 0,
      meanRtMs: mean(this.rts),
      fastestRtMs: this.rts.length > 0 ? Math.min(...this.rts) : 0,
      stdRtMs: std(this.rts),
      rtSamples: this.rts.slice(),
      stability: stabilityFromStd(std(this.rts), 150),
    };
  }

  protected finish(): void {
    if (this.finished) return;
    this.finished = true;
    for (const [, t] of this.active) t.node.remove();
    this.active.clear();
    this.deps.onFinish(this.buildMetrics());
  }

  destroy(): void {
    for (const [, t] of this.active) t.node.remove();
    this.active.clear();
  }
}

