import { clamp } from "../core/stats";
import type { DualMetrics, ReactionMetrics, RhythmMetrics } from "../types";
import type { Engine, EngineDeps } from "./common";
import { ReactionEngine } from "./reaction";
import { RhythmEngine } from "./rhythm";

/**
 * 双任务引擎：节奏跟随 + 视觉反应同时进行。
 * 键盘：空格 = 节奏敲击，F = 反应目标；鼠标：点中心圈 = 节奏，点目标 = 反应，点空白 = 误触。
 */
export class DualEngine implements Engine {
  private rhythm: RhythmEngine;
  private reaction: ReactionEngine;
  private rhythmMetrics: RhythmMetrics | null = null;
  private reactionMetrics: ReactionMetrics | null = null;
  private finished = false;

  constructor(private deps: EngineDeps) {
    const rhythmDeps: EngineDeps = {
      ...deps,
      onFinish: (m) => {
        this.rhythmMetrics = m as RhythmMetrics;
        this.maybeFinish();
      },
      setHud: () => {},
    };
    const reactionDeps: EngineDeps = {
      ...deps,
      onFinish: (m) => {
        this.reactionMetrics = m as ReactionMetrics;
        this.maybeFinish();
      },
      setHud: () => {},
    };
    this.rhythm = new RhythmEngine(rhythmDeps);
    this.reaction = new ReactionEngine(reactionDeps, { densityScale: 0.6 });
  }

  update(): void {
    if (this.finished) return;
    this.rhythm.update();
    this.reaction.update();
    this.deps.setHud({
      节奏命中: String(this.rhythmMetrics?.hits ?? (this.rhythm as unknown as { hits: number }).hits),
      反应命中: String(
        this.reactionMetrics?.hits ?? (this.reaction as unknown as { hits: number }).hits
      ),
    });
  }

  onPointer(x: number, y: number, target: HTMLElement | null): void {
    if (this.deps.settings.inputDevice !== "mouse" || this.finished) return;
    const stage = this.deps.stage.getBoundingClientRect();
    const cx = stage.width / 2;
    const cy = stage.height / 2;
    const distToCenter = Math.hypot(x - cx, y - cy);
    const onTarget = target?.closest(".target");
    if (onTarget) {
      this.reaction.onPointer(x, y, target);
    } else if (distToCenter <= 60) {
      this.rhythm.onPointer(x, y, target);
    } else {
      this.reaction.onPointer(x, y, null);
    }
  }

  onKey(code: string): void {
    if (this.deps.settings.inputDevice !== "keyboard" || this.finished) return;
    if (code === "Space") this.rhythm.onKey("Space");
    else if (code === "KeyF") this.reaction.onKey("KeyF");
  }

  pause(): void {
    this.rhythm.pause();
    this.reaction.pause();
  }

  resume(): void {
    this.rhythm.resume();
    this.reaction.resume();
  }

  private maybeFinish(): void {
    if (this.finished || !this.rhythmMetrics || !this.reactionMetrics) return;
    this.finished = true;
    const baseline = this.deps.baselineRtMs;
    const switchCostMs =
      baseline !== null && this.reactionMetrics.meanRtMs > 0
        ? this.reactionMetrics.meanRtMs - baseline
        : null;
    const interference = clamp(
      0.5 * (1 - this.rhythmMetrics.stability) +
        0.5 * (switchCostMs !== null ? clamp(Math.max(0, switchCostMs) / 300, 0, 1) : 0.3),
      0,
      1
    );
    const metrics: DualMetrics = {
      kind: "dual",
      rhythm: this.rhythmMetrics,
      reaction: this.reactionMetrics,
      switchCostMs,
      interference,
    };
    this.deps.onFinish(metrics);
  }

  destroy(): void {
    this.rhythm.destroy();
    this.reaction.destroy();
  }
}

