}

/**
 * 持续注意与疲劳测试：目标频率逐渐加快，混入需要抑制反应的干扰刺激，
 * 指标按前半段 / 后半段分别统计。
 */
export class AttentionEngine extends ReactionEngine {
  private first = newBucket();
  private second = newBucket();
  private inhibitShown = 0;
  private inhibitErrors = 0;

  constructor(deps: EngineDeps) {
    super(deps, { withInhibitors: true, rampUp: true });
    this.onInhibitClicked = () => {
      this.inhibitErrors++;
    };
  }

  private halfOf(appearAtMs: number): HalfBucket {
    return appearAtMs < this["deps"].durationMs / 2 ? this.first : this.second;
  }

  protected override spawnTarget(event: ReturnType<typeof this.planSlice>): void {
    if (event.inhibit) this.inhibitShown++;
    else this.halfOf(event.appearAtMs).shown++;
    super.spawnTarget(event);
  }

  private planSlice(index: number) {
    return this.plan[index];
  }

  protected override expireTarget(id: number, t: never): void {
    const target = t as { event: { inhibit: boolean; appearAtMs: number } };
    if (!target.event.inhibit) this.halfOf(target.event.appearAtMs).misses++;
    super.expireTarget(id, t);
  }

  protected override hitTarget(t: never): void {
    const target = t as { event: { inhibit: boolean; appearAtMs: number }; shownAtPerf: number };
    if (!target.event.inhibit) {
      const rt =
        performance.now() - this["deps"].settings.inputLatencyMs - target.shownAtPerf;
      this.halfOf(target.event.appearAtMs).rts.push(rt);
      this.halfOf(target.event.appearAtMs).hits++;
    }
    super.hitTarget(t);
  }

  override onPointer(x: number, y: number, target: HTMLElement | null): void {
    const before = this.falseClicks;
    super.onPointer(x, y, target);
    if (this.falseClicks > before) {
      this.halfOf(this["deps"].getElapsed()).falseClicks++;
    }
  }

  override onKey(): void {
    const before = this.falseClicks;
    super.onKey();
    if (this.falseClicks > before) {
      this.halfOf(this["deps"].getElapsed()).falseClicks++;
    }
  }

  protected override buildMetrics(): AttentionMetrics {
    const firstHalf = bucketStats(this.first);
    const secondHalf = bucketStats(this.second);
    return {
      kind: "attention",
      firstHalf,
      secondHalf,
      inhibitShown: this.inhibitShown,
      inhibitErrors: this.inhibitErrors,
      attentionDrop: secondHalf.hitRate < firstHalf.hitRate - 0.05,
      rtDriftMs: secondHalf.meanRtMs - firstHalf.meanRtMs,
      stabilityDropMs: secondHalf.stdRtMs - firstHalf.stdRtMs,
    };
  }
}

