+
+  const getElapsedSafe = () => (startPerf ? performance.now() - startPerf - pausedAccum : 0);
+
+  const createEngine = (): Engine => {
+    const deps = {
+      stage,
+      settings,
+      seed,
+      durationMs,
+      getElapsed,
+      onFinish,
+      setHud,
+      baselineRtMs,
+    };
+    switch (mode) {
+      case "rhythm":
+        return new RhythmEngine(deps);
+      case "reaction":
+        return new ReactionEngine(deps);
+      case "dual":
+        return new DualEngine(deps);
+      case "attention":
+        return new AttentionEngine(deps);
+    }
+  };
+
+  // 倒计时
+  const countdownEl = el("div", { className: "countdown-overlay" }, "3");
+  stage.appendChild(countdownEl);
+  let count = 3;
+  const countTimer = setInterval(() => {
+    count--;
+    if (count <= 0) {
+      clearInterval(countTimer);
+      countdownEl.textContent = "开始!";
+      setTimeout(() => {
+        countdownEl.remove();
+        begin();
+      }, 400);
+    } else {
+      countdownEl.textContent = String(count);
+    }
+  }, 800);
+
+  function begin(): void {
+    startPerf = performance.now();
+    running = true;
+    engine = createEngine();
+    loop();
