+    const elapsed = getElapsed();
+    const remain = Math.max(0, durationMs - elapsed);
+    timeEl.textContent = `${(remain / 1000).toFixed(1)}s`;
+    progressFill.style.width = `${Math.min(100, (elapsed / durationMs) * 100)}%`;
+    engine?.update();
