  const activeProfile = (() => {
    const id = ctx.store.loadActiveProfileId();
    return id ? ctx.store.loadProfiles().find((p) => p.id === id) ?? null : null;
  })();

  const onFinish = (metrics: ModeMetrics) => {
    cleanupRun();
    const record: TestRecord = {
      id: newId(),
      mode,
      profileId: activeProfile?.id ?? null,
      profileName: activeProfile?.name ?? null,
      settings: { ...settings },
      seed,
      startedAt: Date.now(),
      durationMs: getElapsedSafe(),
      metrics,
      score: computeScore(metrics),
      suggestions: generateSuggestions(metrics, settings),
    };
    setLastResult(record);
    setNavGuard(null);
    navigate("/result");
  };

  const getElapsedSafe = () => (startPerf ? performance.now() - startPerf - pausedAccum : 0);

  const createEngine = (): Engine => {
    const deps = {
      stage,
      settings,
      seed,
      durationMs,
      getElapsed,
      onFinish,
      setHud,
      baselineRtMs,
    };
    switch (mode) {
      case "rhythm":
        return new RhythmEngine(deps);
      case "reaction":
        return new ReactionEngine(deps);
      case "dual":
        return new DualEngine(deps);
      case "attention":
        return new AttentionEngine(deps);
    }
  };

  // 倒计时
  const countdownEl = el("div", { className: "countdown-overlay" }, "3");
  stage.appendChild(countdownEl);
  let count = 3;
  const countTimer = setInterval(() => {
    count--;
    if (count <= 0) {
      clearInterval(countTimer);
      countdownEl.textContent = "开始!";
      setTimeout(() => {
        countdownEl.remove();
        begin();
      }, 400);
    } else {
      countdownEl.textContent = String(count);
    }
  }, 800);

  function begin(): void {
    startPerf = performance.now();
    running = true;
    engine = createEngine();
    loop();
  }

  function loop(): void {
    if (!running) return;
    const elapsed = getElapsed();
    const remain = Math.max(0, durationMs - elapsed);
    timeEl.textContent = `${(remain / 1000).toFixed(1)}s`;
    progressFill.style.width = `${Math.min(100, (elapsed / durationMs) * 100)}%`;
    engine?.update();
    raf = requestAnimationFrame(loop);
  }

  let pauseOverlay: HTMLElement | null = null;

  function pause(): void {
    if (!running || paused) return;
    paused = true;
    pauseStart = performance.now();
    engine?.pause();
    pauseBtn.textContent = "继续";
    pauseOverlay = el(
      "div",
      { className: "pause-overlay" },
      el("h3", {}, "已暂停"),
      el(
        "div",
        { className: "row" },
        btn("继续", "btn btn-primary", () => resume()),
        btn("重新开始", "btn", () => restart()),
        btn("退出测试", "btn btn-danger", () => quit())
      )
    );
    stage.appendChild(pauseOverlay);
  }

  function resume(): void {
    if (!paused) return;
    paused = false;
    pausedAccum += performance.now() - pauseStart;
    engine?.resume();
    pauseBtn.textContent = "暂停";
    pauseOverlay?.remove();
    pauseOverlay = null;
  }

  function restart(): void {
    cleanupRun();
    setNavGuard(null);
    const hash = `#/test/${mode}?seed=${Math.floor(Math.random() * 2 ** 31)}`;
    // 通过替换 hash 强制重新渲染
    if (window.location.hash === hash) window.location.hash = `#/test/${mode}`;
    else window.location.hash = hash;
  }

  function quit(): void {
    if (!window.confirm("测试进行中，确定要退出吗？当前结果将丢失。")) return;
    cleanupRun();
    setNavGuard(null);
    navigate("/tests");
  }

  function cleanupRun(): void {
    running = false;
    cancelAnimationFrame(raf);
    clearInterval(countTimer);
    engine?.destroy();
    engine = null;
  }

  // 输入
  const onPointer = (e: PointerEvent) => {
    if (!running || paused || !engine) return;
    const rect = stage.getBoundingClientRect();
    engine.onPointer(e.clientX - rect.left, e.clientY - rect.top, e.target as HTMLElement | null);
  };
  const onKey = (e: KeyboardEvent) => {
    if (!running || paused || !engine) return;
    if (e.repeat) return;
    if (e.code === "Space" || e.code === "KeyF") {
      e.preventDefault();
      engine.onKey(e.code);
    }
  };
  stage.addEventListener("pointerdown", onPointer);
  window.addEventListener("keydown", onKey);

  // 防误触离开
  setNavGuard(() => window.confirm("测试进行中，确定要离开吗？当前结果将丢失。"));
  const onBeforeUnload = (e: BeforeUnloadEvent) => {
    if (running) e.preventDefault();
  };
  window.addEventListener("beforeunload", onBeforeUnload);

  pauseBtn.addEventListener("click", () => {
    if (paused) resume();
  });

  return () => {
    cleanupRun();
    setNavGuard(null);
    stage.removeEventListener("pointerdown", onPointer);
    window.removeEventListener("keydown", onKey);
    window.removeEventListener("beforeunload", onBeforeUnload);
  };
}

