import { el } from "../ui";
import { pageContainer, type AppCtx } from "./layout";

export function testSelectPage(root: HTMLElement, ctx: AppCtx): void {
  const main = pageContainer(root, "tests", ctx);
  const settings = ctx.store.loadSettings();
  const activeId = ctx.store.loadActiveProfileId();
  const profile = activeId ? ctx.store.loadProfiles().find((p) => p.id === activeId) : null;

  main.appendChild(el("h2", {}, "选择测试"));
  main.appendChild(
    el(
      "p",
      { className: "muted" },
      `当前参数：${settings.bpm}BPM · 细分 1/${settings.subdivision * 4} · ${settings.durationSec}s · ${
        settings.difficulty
      } · ${settings.inputDevice === "keyboard" ? "键盘" : "鼠标"} · 延迟补偿 ${
        settings.audioLatencyMs + settings.inputLatencyMs
      }ms`,
      profile ? ` · 配置「${profile.name}」` : ""
    )
  );

  const modes: [string, string, string][] = [
    ["rhythm", "🥁 节奏跟随", "跟随变化的节拍敲击，测量时间偏差、命中率与连击。"],
    ["reaction", "🎯 视觉反应", "尽快响应随机出现的目标，测量反应时间与误触。"],
    ["dual", "🧠 双任务", "节奏 + 反应同时进行，测量任务切换损失与干扰。"],
    ["attention", "⏳ 持续注意", "长时间连续测试，含抑制刺激，分阶段评估疲劳。"],
  ];
  const grid = el("div", { className: "grid cols-2" });
  for (const [mode, title, desc] of modes) {
    const card = el(
      "div",
      { className: "card" },
      el("h3", {}, title),
      el("p", { className: "muted" }, desc),
      el("span", { className: "btn btn-primary", style: "margin-top:8px;display:inline-block" }, "开始")
    );
    card.addEventListener("click", () => {
      window.location.hash = `#/test/${mode}`;
    });
    grid.appendChild(card);
  }
  main.appendChild(grid);
}

