    main.appendChild(el("p", {}, "没有可显示的测试结果。"));
    main.appendChild(el("a", { className: "btn btn-primary", href: "#/tests" }, "去选择测试"));
    return;
  }

  main.appendChild(
    el(
      "h2",
      {},
      `${MODE_LABELS[rec.mode]}测试结果 `,
      rec.profileName ? el("span", { className: "tag" }, rec.profileName) : ""
    )
  );

  // 综合分数
  const scorePanel = el("div", { className: "panel", style: "display:flex;gap:24px;align-items:center;flex-wrap:wrap" });
  scorePanel.appendChild(el("div", { className: "score-big" }, String(rec.score)));
  scorePanel.appendChild(
    el(
      "div",
      {},
      el("div", { className: "muted" }, "综合分数（0-100）"),
      el(
        "div",
        { className: "muted" },
        `${rec.settings.bpm}BPM · ${rec.settings.difficulty} · ${rec.settings.durationSec}s · ${
          rec.settings.inputDevice === "keyboard" ? "键盘" : "鼠标"
        }`
      )
    )
  );
  main.appendChild(scorePanel);

  // 指标
  const metricsPanel = el("div", { className: "panel" });
  metricsPanel.appendChild(el("h3", {}, "详细指标"));
  const grid = el("div", { className: "metric-grid" });
  const m = rec.metrics;
  if (m.kind === "rhythm") {
    grid.appendChild(metric("命中率", fmtPct(m.hitRate)));
    grid.appendChild(metric("平均时间偏差", fmtMs(m.meanOffsetMs, 1)));
    grid.appendChild(metric("偏差标准差", fmtMs(m.stdOffsetMs, 1)));
    grid.appendChild(metric("最快偏差", fmtMs(m.fastestOffsetMs, 1)));
    grid.appendChild(metric("漏拍", String(m.misses)));
    grid.appendChild(metric("失误（错误时机）", String(m.wrongTaps)));
    grid.appendChild(metric("最大连击", String(m.maxCombo)));
    grid.appendChild(metric("节奏稳定性", fmtPct(m.stability)));
    grid.appendChild(metric("抢拍/拖拍", biasLabel(m.bias)));
  } else if (m.kind === "reaction") {
    grid.appendChild(metric("点击成功率", fmtPct(m.hitRate)));
    grid.appendChild(metric("平均反应时间", fmtMs(m.meanRtMs, 1)));
    grid.appendChild(metric("最快反应时间", fmtMs(m.fastestRtMs, 1)));
    grid.appendChild(metric("反应标准差", fmtMs(m.stdRtMs, 1)));
    grid.appendChild(metric("漏点", String(m.misses)));
    grid.appendChild(metric("误触", String(m.falseClicks)));
    grid.appendChild(metric("反应稳定性", fmtPct(m.stability)));
  } else if (m.kind === "dual") {
    grid.appendChild(metric("节奏命中率", fmtPct(m.rhythm.hitRate)));
    grid.appendChild(metric("节奏平均偏差", fmtMs(m.rhythm.meanOffsetMs, 1)));
    grid.appendChild(metric("反应命中率", fmtPct(m.reaction.hitRate)));
    grid.appendChild(metric("平均反应时间", fmtMs(m.reaction.meanRtMs, 1)));
    grid.appendChild(
      metric("任务切换损失", m.switchCostMs === null ? "无基线" : fmtMs(m.switchCostMs, 1))
    );
    grid.appendChild(metric("干扰程度", fmtPct(m.interference)));
  } else {
    grid.appendChild(metric("前半段命中率", fmtPct(m.firstHalf.hitRate)));
    grid.appendChild(metric("后半段命中率", fmtPct(m.secondHalf.hitRate)));
    grid.appendChild(metric("前半段反应", fmtMs(m.firstHalf.meanRtMs, 1)));
    grid.appendChild(metric("后半段反应", fmtMs(m.secondHalf.meanRtMs, 1)));
    grid.appendChild(metric("反应漂移", fmtMs(m.rtDriftMs, 1)));
    grid.appendChild(metric("抑制错误", `${m.inhibitErrors}/${m.inhibitShown}`));
    grid.appendChild(metric("注意力下降", m.attentionDrop ? "是" : "否"));
  }
  metricsPanel.appendChild(grid);

  // 反应时间分布
  const rtSamples =
    m.kind === "reaction" ? m.rtSamples : m.kind === "dual" ? m.reaction.rtSamples : [];
  if (rtSamples.length >= 3) {
    const buckets = histogram(rtSamples, 10);
    const max = Math.max(...buckets.map((b) => b.count));
    const chart = el("div", { className: "hist-chart" });
    for (const b of buckets) {
      const bar = el("div", { className: "hist-bar" });
      bar.style.height = `${(b.count / max) * 100}%`;
      bar.title = `${Math.round(b.lo)}-${Math.round(b.hi)}ms: ${b.count}次`;
      chart.appendChild(bar);
    }
    metricsPanel.appendChild(el("h3", { style: "margin-top:16px" }, "反应速度分布"));
    metricsPanel.appendChild(chart);
    metricsPanel.appendChild(
      el(
        "div",
        { className: "muted", style: "margin-top:4px" },
        `${Math.round(buckets[0].lo)}ms — ${Math.round(buckets[buckets.length - 1].hi)}ms`
      )
    );
  }

  // 持续注意分阶段表
  if (m.kind === "attention") {
    const table = el("table", { className: "data", style: "margin-top:16px" });
    table.appendChild(
      el(
        "tr",
        {},
        el("th", {}, "阶段"),
        el("th", {}, "命中率"),
        el("th", {}, "平均反应"),
        el("th", {}, "反应波动"),
        el("th", {}, "漏点"),
        el("th", {}, "误触")
      )
    );
    for (const [label, h] of [
      ["前半段", m.firstHalf],
      ["后半段", m.secondHalf],
    ] as const) {
      table.appendChild(
        el(
          "tr",
          {},
          el("td", {}, label),
          el("td", {}, fmtPct(h.hitRate)),
          el("td", {}, fmtMs(h.meanRtMs, 1)),
          el("td", {}, fmtMs(h.stdRtMs, 1)),
          el("td", {}, String(h.misses)),
          el("td", {}, String(h.falseClicks))
        )
      );
    }
    metricsPanel.appendChild(table);
  }
  main.appendChild(metricsPanel);

  // 建议
  const sugPanel = el("div", { className: "panel" });
  sugPanel.appendChild(el("h3", {}, "训练建议（由本次数据生成）"));
  const ul = el("ul", { className: "suggestion-list" });
  for (const s of rec.suggestions) ul.appendChild(el("li", {}, s));
  sugPanel.appendChild(ul);
  main.appendChild(sugPanel);

  // 配置对比
  renderComparison(main, ctx, rec);

  // 操作
  const saveBtn = btn(isLastSaved() ? "已保存" : "保存本次记录", "btn btn-success", () => {
    ctx.store.addRecord(rec);
    markLastSaved();
    saveBtn.disabled = true;
    saveBtn.textContent = "已保存";
    toast("记录已保存");
  });
  saveBtn.disabled = isLastSaved();
  main.appendChild(
    el(
      "div",
      { className: "row" },
      saveBtn,
      btn("重新测试", "btn btn-primary", () => navigate(`/test/${rec.mode}`)),
      btn("相同规则重测", "btn", () => navigate(`/test/${rec.mode}?seed=${rec.seed}`)),
      btn("返回设置", "btn btn-ghost", () => navigate("/settings")),
      el("a", { className: "btn btn-ghost", href: "#/records" }, "查看记录")
    )
  );
}

/** 同模式不同训练配置的最近一次成绩对比 */
function renderComparison(main: HTMLElement, ctx: AppCtx, current: TestRecord): void {
  const same = ctx.store.loadRecords().filter((r) => r.mode === current.mode);
  const byProfile = new Map<string, TestRecord>();
  for (const r of same) {
    const key = r.profileName ?? "未命名配置";
    if (!byProfile.has(key)) byProfile.set(key, r);
  }
  const currentKey = current.profileName ?? "未命名配置";
  if (!byProfile.has(currentKey)) byProfile.set(currentKey, current);
  if (byProfile.size < 2) return;

  const panel = el("div", { className: "panel" });
  panel.appendChild(el("h3", {}, "不同训练配置对比（同模式最近一次）"));
  const rows: [string, (r: TestRecord) => string][] = [
    ["命中率", (r) => hitRateOf(r)],
    ["平均反应时间", (r) => rtOf(r)],
    ["平均节奏偏差", (r) => offsetOf(r)],
    ["持续注意（前→后）", (r) => attentionOf(r)],
    ["综合分数", (r) => String(r.score)],
  ];
  const table = el("table", { className: "data" });
  const head = el("tr", {}, el("th", {}, "指标"));
  for (const key of byProfile.keys()) head.appendChild(el("th", {}, key));
  table.appendChild(head);
  for (const [label, fn] of rows) {
    const tr = el("tr", {}, el("td", {}, label));
    for (const rec of byProfile.values()) tr.appendChild(el("td", {}, fn(rec)));
    table.appendChild(tr);
  }
  panel.appendChild(table);
  main.appendChild(panel);
}

function hitRateOf(r: TestRecord): string {
  const m = r.metrics;
  if (m.kind === "rhythm") return fmtPct(m.hitRate);
  if (m.kind === "reaction") return fmtPct(m.hitRate);
  if (m.kind === "dual") return `${fmtPct(m.rhythm.hitRate)} / ${fmtPct(m.reaction.hitRate)}`;
  return `${fmtPct(m.firstHalf.hitRate)} / ${fmtPct(m.secondHalf.hitRate)}`;
}

function rtOf(r: TestRecord): string {
  const m = r.metrics;
  if (m.kind === "reaction") return fmtMs(m.meanRtMs, 0);
  if (m.kind === "dual") return fmtMs(m.reaction.meanRtMs, 0);
  if (m.kind === "attention") return `${fmtMs(m.firstHalf.meanRtMs, 0)}→${fmtMs(m.secondHalf.meanRtMs, 0)}`;
  return "—";
}

function offsetOf(r: TestRecord): string {
  const m = r.metrics;
  if (m.kind === "rhythm") return fmtMs(m.meanOffsetMs, 1);
  if (m.kind === "dual") return fmtMs(m.rhythm.meanOffsetMs, 1);
  return "—";
}

function attentionOf(r: TestRecord): string {
  const m = r.metrics;
  if (m.kind === "attention") {
    return `${fmtPct(m.firstHalf.hitRate)} → ${fmtPct(m.secondHalf.hitRate)}`;
  }
  return "—";
}

