  it("输入延迟补偿从敲击时间中扣除", () => {
    expect(computeOffsetMs(1030, 1000, 0, 30)).toBe(0);
  });

  it("反应时间 = 输入时间 - 输入补偿 - 目标出现时间", () => {
    expect(computeReactionMs(1250, 1000, 20)).toBe(230);
  });
});

describe("命中判断", () => {
  it("不同难度窗口不同", () => {
    expect(hitWindowMs("easy")).toBe(150);
    expect(hitWindowMs("medium")).toBe(100);
    expect(hitWindowMs("hard")).toBe(60);
  });

  it("窗口内为命中，窗口外为失误", () => {
    expect(isHit(99, 100)).toBe(true);
    expect(isHit(-100, 100)).toBe(true);
    expect(isHit(101, 100)).toBe(false);
    expect(isHit(-101, 100)).toBe(false);
  });
});

describe("节奏倾向与稳定性", () => {
  it("平均偏差 <= -20 判定抢拍，>= 20 判定拖拍", () => {
    expect(rhythmBias(-30)).toBe("early");
    expect(rhythmBias(30)).toBe("late");
    expect(rhythmBias(0)).toBe("neutral");
  });

  it("标准差越小稳定性越高，且限制在 0..1", () => {
    expect(stabilityFromStd(0)).toBe(1);
    expect(stabilityFromStd(10000)).toBe(0);
    const mid = stabilityFromStd(60);
    expect(mid).toBeGreaterThan(0);
    expect(mid).toBeLessThan(1);
  });
});

describe("校准延迟估算", () => {
  it("返回样本均值与标准差", () => {
    const { meanMs, stdMs } = estimateLatencyFromOffsets([100, 110, 90, 105, 95]);
    expect(meanMs).toBeCloseTo(100, 5);
    expect(stdMs).toBeGreaterThan(0);
  });

  it("过滤超过 ±400ms 的异常值", () => {
    const { meanMs, used } = estimateLatencyFromOffsets([100, 100, 100, 100, 100, 2000]);
    expect(used).toHaveLength(5);
    expect(meanMs).toBeCloseTo(100, 5);
  });

  it("空数组返回 0", () => {
    const { meanMs, stdMs } = estimateLatencyFromOffsets([]);
    expect(meanMs).toBe(0);
    expect(stdMs).toBe(0);
  });
});

