import { describe, expect, it } from "vitest";
import { createRng, generateBeatPlan, generateTargetPlan } from "../src/core/targets";

describe("目标生成", () => {
  it("同一种子生成完全相同的目标计划（保证配置间公平对比）", () => {
    const a = generateTargetPlan({ durationMs: 20000, difficulty: "medium", seed: 42 });
    const b = generateTargetPlan({ durationMs: 20000, difficulty: "medium", seed: 42 });
    expect(a).toEqual(b);
  });

  it("不同种子生成不同的目标计划", () => {
    const a = generateTargetPlan({ durationMs: 20000, difficulty: "medium", seed: 1 });
    const b = generateTargetPlan({ durationMs: 20000, difficulty: "medium", seed: 2 });
    expect(a).not.toEqual(b);
  });

  it("目标位置在舞台范围内，大小在合理区间", () => {
    const plan = generateTargetPlan({ durationMs: 30000, difficulty: "medium", seed: 7 });
    expect(plan.length).toBeGreaterThan(5);
    for (const t of plan) {
      expect(t.x).toBeGreaterThanOrEqual(0.08);
      expect(t.x).toBeLessThanOrEqual(0.92);
      expect(t.y).toBeGreaterThanOrEqual(0.08);
      expect(t.y).toBeLessThanOrEqual(0.92);
      expect(t.size).toBeGreaterThanOrEqual(40);
      expect(t.size).toBeLessThanOrEqual(90);
      expect(t.appearAtMs).toBeLessThan(30000);
    }
  });

  it("困难难度目标数量多于简单难度（间隔更短）", () => {
    const easy = generateTargetPlan({ durationMs: 30000, difficulty: "easy", seed: 5 });
    const hard = generateTargetPlan({ durationMs: 30000, difficulty: "hard", seed: 5 });
    expect(hard.length).toBeGreaterThan(easy.length);
  });

  it("持续注意模式包含抑制刺激且频率逐渐加快", () => {
    const plan = generateTargetPlan({
      durationMs: 60000,
      difficulty: "medium",
      seed: 9,
      withInhibitors: true,
      rampUp: true,
    });
    expect(plan.some((t) => t.inhibit)).toBe(true);
    const normals = plan.filter((t) => !t.inhibit);
    const half = 30000;
    const firstGaps: number[] = [];
    const secondGaps: number[] = [];
    for (let i = 1; i < normals.length; i++) {
      const gap = normals[i].appearAtMs - normals[i - 1].appearAtMs;
      if (normals[i].appearAtMs < half) firstGaps.push(gap);
      else secondGaps.push(gap);
    }
    const avg = (xs: number[]) => xs.reduce((a, b) => a + b, 0) / xs.length;
    expect(avg(secondGaps)).toBeLessThan(avg(firstGaps));
  });

  it("伪随机数生成器可复现", () => {
    const r1 = createRng(123);
    const r2 = createRng(123);
