    expect(s.loadSettings()).toEqual(DEFAULT_SETTINGS);
    const issues = s.getIssues();
    expect(issues).toHaveLength(1);
    expect(issues[0].key).toBe(KEYS.settings);
  });

  it("repair 移除损坏键并清除问题", () => {
    const storage = fakeStorage();
    storage.setItem(KEYS.records, "not-json");
