import { describe, expect, it } from "vitest";
import { recordsToCsv, recordsToJson } from "../src/core/export";
import { DEFAULT_SETTINGS, type TestRecord } from "../src/types";

function rec(id: string): TestRecord {
  return {
    id,
    mode: "reaction",
    profileId: "p1",
    profileName: "测试配置",
    settings: { ...DEFAULT_SETTINGS },
    seed: 7,
    startedAt: 1700000000000,
    durationMs: 30000,
    metrics: {
      kind: "reaction",
      targetsShown: 10,
      hits: 8,
      misses: 2,
      falseClicks: 1,
      hitRate: 0.8,
      meanRtMs: 300,
      fastestRtMs: 210,
      stdRtMs: 50,
      rtSamples: [300, 310, 290],
      stability: 0.7,
    },
    score: 75,
    suggestions: ["测试建议"],
  };
}

describe("结果导出", () => {
  it("JSON 导出可解析且内容完整", () => {
    const parsed = JSON.parse(recordsToJson([rec("a")]));
    expect(parsed).toHaveLength(1);
    expect(parsed[0].id).toBe("a");
    expect(parsed[0].metrics.meanRtMs).toBe(300);
  });

  it("CSV 导出包含表头与数据行", () => {
    const csv = recordsToCsv([rec("a"), rec("b")]);
    const lines = csv.split("\n");
    expect(lines).toHaveLength(3);
    expect(lines[0]).toContain("score");
    expect(lines[1]).toContain("a");
  });

  it("空记录导出为空字符串", () => {
    expect(recordsToCsv([])).toBe("");
  });
});

