      const hasTarget = await page.$(".target");
      if (hasTarget) await page.keyboard.press("KeyF");
      else await page.keyboard.press("Space");
      await sleep(450);
    }
    await page.waitForSelector("text=双任务测试结果", { timeout: 15000 });
    await page.screenshot({ path: `${SHOTS}/06-dual-result.png` });
    await page.click("text=保存本次记录");
    await page.waitForSelector("text=记录已保存");
    ok("双任务测试完成并保存");

    // ---------- 7. 持续注意 ----------
    await page.click("a.navlink >> text=测试");
    await page.click("text=⏳ 持续注意");
    await page.waitForSelector(".countdown-overlay", { state: "detached", timeout: 8000 });
    const attStart = Date.now();
    while (Date.now() - attStart < 13500) {
      const normal = await page.$(".target:not(.inhibit)");
      if (normal) await page.keyboard.press("KeyF");
      await sleep(120);
    }
    await page.waitForSelector("text=持续注意测试结果", { timeout: 15000 });
    await page.screenshot({ path: `${SHOTS}/07-attention-result.png` });
    await page.click("text=保存本次记录");
    await page.waitForSelector("text=记录已保存");
    ok("持续注意测试完成并保存");

    // ---------- 8. 配置 B（鼠标）相同规则重测视觉反应 + 对比 ----------
    await page.click("a.navlink >> text=设置");
    await page.locator("tr", { hasText: "配置B-鼠标" }).locator("text=应用").click();
    await page.waitForSelector("text=已应用配置");
    await page.goto(`${BASE}/#/test/reaction?seed=${seedA}`);
    await page.waitForSelector(".countdown-overlay", { state: "detached", timeout: 8000 });
    const react2Start = Date.now();
    while (Date.now() - react2Start < 13500) {
      const target = await page.$(".target");
      if (target) {
        try {
          await target.click({ timeout: 300 });
        } catch {
          /* 目标已消失 */
        }
      }
      await sleep(80);
    }
    await page.waitForSelector("text=视觉反应测试结果", { timeout: 15000 });
    await page.screenshot({ path: `${SHOTS}/08-reaction-result-mouse.png` });
    await page.click("text=保存本次记录");
    await page.waitForSelector("text=记录已保存");
    await page.waitForSelector("text=不同训练配置对比");
    await page.screenshot({ path: `${SHOTS}/09-profile-comparison.png` });
    ok("配置 B 相同规则重测 + 配置对比展示");

    // ---------- 9. 记录页：查看 / 删除 / 导出 / 清空 ----------
    await page.click("a.navlink >> text=记录");
    await page.waitForSelector("h2 >> text=测试记录");
    const rowCount = await page.locator("table.data tr").count();
    if (rowCount < 5) throw new Error(`记录数量异常: ${rowCount}`);
    await page.screenshot({ path: `${SHOTS}/10-records.png` });
    await page.locator("table.data tr").nth(1).locator("text=查看").click();
    await page.waitForSelector("h2 >> text=测试结果", { timeout: 5000 }).catch(() => {});
    await page.waitForSelector("text=详细指标");
    ok("查看历史记录详情");
    await page.click("a.navlink >> text=记录");
    const dl1Promise = page.waitForEvent("download", { timeout: 8000 });
    await page.click("text=导出 JSON");
    const dl1 = await dl1Promise;
    if (await dl1.failure()) throw new Error("JSON 导出失败");
    ok("JSON 导出可用");
    const dl2Promise = page.waitForEvent("download", { timeout: 8000 });
    await page.click("text=导出 CSV");
    const dl2 = await dl2Promise;
    if (await dl2.failure()) throw new Error("CSV 导出失败");
    ok("CSV 导出可用");
    const before = await page.locator("table.data tr").count();
    await page.locator("table.data tr").nth(1).locator("text=删除").click();
    await page.click(".modal >> text=确认");
    await page.waitForSelector("text=记录已删除");
    const after = await page.locator("table.data tr").count();
    if (after !== before - 1) throw new Error("单条删除失败");
    ok("单条删除");
    await page.reload();
    await page.waitForSelector("h2 >> text=测试记录");
    if ((await page.locator("table.data tr").count()) !== after) throw new Error("刷新后记录丢失");
    ok("刷新后记录保持");
    await page.click("text=清空全部记录");
    await page.click(".modal >> text=全部删除");
    await page.waitForSelector("text=暂无测试记录");
    ok("清空全部记录");

    // ---------- 10. 数据损坏提示与恢复 ----------
    await page.evaluate(() => localStorage.setItem("rrt.records.v1", "{broken json!!!"));
    await page.reload();
    await page.waitForSelector("text=检测到本地数据损坏");
    await page.screenshot({ path: `${SHOTS}/11-corruption.png` });
    await page.click("text=恢复损坏项为默认");
    await page.waitForSelector("h2 >> text=测试记录");
    if (await page.$("text=检测到本地数据损坏")) throw new Error("损坏恢复失败");
    ok("数据损坏提示与恢复");

    console.log(`\n全部端到端检查通过（${passed} 项）。`);
  } finally {
    await browser.close();
    server.kill();
  }
}

main().catch((err) => {
  console.error("E2E 失败:", err);
  process.exit(1);
});

